class Solution {
    public int countSegments(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            boolean currentIsSegmentChar = s.charAt(i) != ' ';
            boolean previousIsSeparator = i == 0 || s.charAt(i - 1) == ' ';
            if (currentIsSegmentChar && previousIsSeparator) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int countSegments(String s) {
        int count = 0;
        for (int i = 0; i < s.length(); i++) {
            boolean currentIsSegmentChar = s.charAt(i) != ' ';
            boolean nextIsSeparator = i == s.length() - 1 || s.charAt(i + 1) == ' ';
            if (currentIsSegmentChar && nextIsSeparator) {
                count++;
            }
        }
        return count;
    }
}

class Solution {
    public int countSegments(String s) {
        int count = 0;
        boolean inside = false;
        for (int i = 0; i < s.length(); i++) {
            if (s.charAt(i) == ' ') {
                inside = false;
            } else if (!inside) {
                count++;
                inside = true;
            }
        }
        return count;
    }
}

class Solution {
    public int countSegments(String s) {
        int count = 0;
        int i = 0;
        while (i < s.length()) {
            while (i < s.length() && s.charAt(i) == ' ') {
                i++;
            }
            if (i == s.length()) {
                break;
            }
            count++;
            while (i < s.length() && s.charAt(i) != ' ') {
                i++;
            }
        }
        return count;
    }
}

class Solution {
    public int countSegments(String s) {
        String trimmed = s.trim();
        if (trimmed.isEmpty()) {
            return 0;
        }
        String[] parts = trimmed.split(" +");
        return parts.length;
    }
}
